class BruteForce:
    """One stack with the oldest on top; every push pours everything out and back, O(n)."""

    def __init__(self):
        self.main = []

    def push(self, x: int) -> None:
        helper = []
        while self.main:
            helper.append(self.main.pop())
        self.main.append(x)
        while helper:
            self.main.append(helper.pop())

    def pop(self) -> int:
        return self.main.pop()

    def peek(self) -> int:
        return self.main[-1]

    def empty(self) -> bool:
        return not self.main

