class RecentCounter:
    def __init__(self):
        self.q = deque()

    def ping(self, t: int) -> int:
        self.q.append(t)
        while self.q[0] < t - 3000:     # oldest first, so expiry is always at the front
            self.q.popleft()
        return len(self.q)

