def brute_force(senate: str) -> str:
    n = len(senate)
    banned = [False] * n
    while True:
        for i in range(n):
            if banned[i]:
                continue
            j = (i + 1) % n                     # scan for the next live opponent
            while j != i and (banned[j] or senate[j] == senate[i]):
                j = (j + 1) % n
            if j == i:                          # no opponent left
                return "Radiant" if senate[i] == "R" else "Dire"
            banned[j] = True

